mapper.select:
SELECT wmfr.freeze_type, wmfr.freeze_source_id, wmfr.freeze_source_sn, MAX(wmfr.frozen_time) AS frozen_time, MAX(wmfr.operator_name) AS operator_name, GROUP_CONCAT(wmfr.id) AS idList FROM wms_material_freeze_record wmfr LEFT JOIN wms_material_freeze wmf ON wmf.id = wmfr.material_freeze_id WHERE wmfr.bool_delete_enum = 0 AND wmfr.freeze_type != ${@com.hzchum.scim.wms.core.api.enums.MaterialFreezeTypeEnum@MANUAL.getType()}
AND wmfr.freeze_type IN
#{item}
and wmf.basic_class & #{ basicClass} > 0
GROUP BY wmfr.freeze_type, wmfr.freeze_source_id, wmfr.freeze_source_sn

SELECT wmfr.freeze_type, DATE_FORMAT(wmfr.frozen_time, '%Y-%m-%d') AS frozen_time, wmfr.operator_name, GROUP_CONCAT(wmfr.id) AS idList FROM wms_material_freeze_record wmfr LEFT JOIN wms_material_freeze wmf ON wmf.id = wmfr.material_freeze_id WHERE wmfr.bool_delete_enum = 0 AND wmfr.freeze_type = ${@com.hzchum.scim.wms.core.api.enums.MaterialFreezeTypeEnum@MANUAL.getType()}
AND wmfr.freeze_type IN
#{item}
and wmf.basic_class & #{ basicClass} > 0
GROUP BY wmfr.freeze_type, DATE_FORMAT(wmfr.frozen_time, '%Y-%m-%d'), wmfr.operator_name

SELECT free.material_inventory_id, free.basic_class, free.classify_id, free.total_freeze_types, free.warehouse_type, free.material_is_whole, free.specification, free.bool_party_a, free.project_id, free.warehouse_id, free.theory_thickness, free.brand, free.heat_no_and_batch_no, free.color, free.total_basic_class, free.length, free.thickness, free.width, free.standard_id, free.standard_name, free.monomer_id, free.area_id, free.workshop_id, rec.id, rec.quantity as total_quantity, rec.mete as total_mete FROM wms_material_freeze_record as rec left join wms_material_freeze as free on free.id = rec.material_freeze_id and free.bool_delete_enum = 0 where rec.bool_delete_enum = 0
and rec.id in
#{item}
and free.material_is_whole = #{materialIsWhole}
and free.workshop_id = #{workshopId}
and free.warehouse_id = #{warehouseId}
and free.theory_thickness = #{theoryThickness}
and free.thickness = #{thickness}
and free.basic_class = #{ basicClass}
and free.width = #{width}
and free.length = #{length}
and free.steel_coil_length >= #{minLength}
and free.steel_coil_length <= #{maxLength}
and free.brand like CONCAT('%', #{brand},'%')
and free.color like CONCAT('%', #{color},'%')
and free.specification like CONCAT('%', #{specification},'%')
and free.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
and free.classify_id in
#{item}
and classify_id = #{classifyId}
